(NULL, 'stem_vessel_wall_fraction', 'Fraction of xylem vessels comprised of cell wall, calculated as the ratio of xylem vessel cell wall cross-sectional area to total xylem vessel cross-sectional area.', 'mm2/mm2', 'num', 'xylem vessel wall fraction', NULL, '0.001', '1.0', FALSE),
(NULL, 'stem_xylem_vulnerability_index', 'The ratio of a stem''s average xylem vessel diameter to the stem''s xylem vessel density, an index of sap conductance and xylem vessel susceptibility to vessel cavitation.', 'um.m2/{count}', 'num', 'Xylem vulnerability index', NULL, '0.05', '1000.0', FALSE),
(NULL, 'wood_axial_parenchyma_fraction', 'The fraction of a cross-section of sapwood comprised of axial parenchyma. It is calculated as the ratio of total axial parenchyma cross-sectional area to sapwood cross-sectional area.', 'mm2/mm2', 'num', 'Wood axial parenchyma fraction', NULL, '0.001', '1.0', FALSE),
(NULL, 'wood_conduit_fraction', 'The fraction of a cross-section of sapwood comprised of all water transport conduits, including both xylem vessels and tracheids. It is calculated as the ratio of total conduit cross-sectional area to sapwood cross-sectional area.', 'mm2/mm2', 'num', 'Wood conduit fraction', NULL, '0.01', '1.0', FALSE),
(NULL, 'wood_fibre_fraction', 'The fraction of a cross-section of sapwood comprised of fibres. It is calculated as the ratio of total fibre cross-sectional area to sapwood cross-sectional area.', 'mm2/mm2', 'num', 'Wood fibre fraction', NULL, '0.01', '1.0', FALSE),
(NULL, 'wood_ray_parenchyma_fraction', 'The fraction of a cross-section of sapwood comprised of rays. It is calculated as the ratio of total ray cross-sectional area to sapwood cross-sectional area.', 'mm2/mm2', 'num', 'Wood ray parenchyma fraction', NULL, '0.01', '1.0', FALSE),
(NULL, 'wood_tracheid_fraction', 'The fraction of a cross-section of sapwood comprised of tracheids. It is calculated as the ratio of total tracheid cross-sectional area to sapwood cross-sectional area.', 'mm2/mm2', 'num', 'Wood tracheid fraction', NULL, '0.0', '1.0', FALSE),
(NULL, 'leaf_work_to_punch', 'The force (work) required to punch a hole through a leaf lamina, generally with a punch and die. This is a measure of leaf compressive strength or toughness.', 'N/m', 'num', 'Leaf work to punch', NULL, '0.5', '10000.0', FALSE),
(NULL, 'leaf_work_to_punch_adjusted', 'The force (work) required to punch a hole through a leaf lamina, generally with a punch and die, adjusted for leaf thickness. This is a measure of leaf compressive strength or toughness.', 'N/m2', 'num', 'Leaf specific work to punch', NULL, '1000.0', '30000000.0', FALSE),
(NULL, 'leaf_work_to_shear', 'The force (work) required to shear a leaf. This is a measure of leaf compressive strength or toughness that is equivalent to cutting a leaf with scissors.', 'N', 'num', 'Leaf work to shear', NULL, '0.01', '10.0', FALSE),
(NULL, 'leaf_work_to_shear_adjusted', 'The force (work) required to shear a leaf, adjusted to leaf thickness; also referred to as ''fracture toughness''. This is a measure of leaf compressive strength or toughness that is equivalent to cutting a leaf with scissors.', 'N/m', 'num', 'Leaf specific work to shear (fracture toughness)', NULL, '100.0', '10000.0', FALSE),
(NULL, 'leaf_work_to_tear', 'The force (work) required to tear/rip a leaf. This is a measure of leaf tensile strength.', 'N', 'num', 'Leaf work to tear', NULL, '0.01', '50.0', FALSE),
(NULL, 'leaf_work_to_tear_adjusted', 'The force (work) required to tear/rip a leaf, adjusted to leaf thickness. This is a measure of leaf tensile strength.', 'N/m', 'num', 'Leaf specific work to tear', NULL, '10.0', '15000.0', FALSE),
(NULL, 'bark_modulus_of_elasticity', 'A measure of stem stiffness and elasticity, which is how much the bark is deformed elastically (bends) under stress. It is calculated as the ratio of the force applied to bark per unit area (stress) to the bark''s deformation (bending). The trait is also called Young''s modulus for bark.', 'MPa', 'num', 'Bark modulus of elasticity', NULL, '10.0', '100000.0', FALSE),
(NULL, 'stem_modulus_of_elasticity', 'A measure of stem stiffness and elasticity, which is how much the stem is deformed elastically (bends) under stress. It is calculated as the ratio of the force applied to stem per unit area (stress) to the stem''s deformation (bending).  This is the modulus of a compound tissue made up of bark and wood (or xylem) and potentially pith and could also be called structural modulus of elasticity. Trait is also called Young''s modulus for a stem.', 'MPa', 'num', 'Stem modulus of elasticity', NULL, '10.0', '100000.0', FALSE),
(NULL, 'xylem_modulus_of_elasticity', 'A measure of wood stiffness and elasticity, which is how much wood (secondary xylem) is deformed elastically (bends) under stress. It is calculated as the ratio of the force applied to wood per unit area (stress) to the stem''s deformation (bending).  This is the modulus of elasticity explicitly for xylem (wood). Trait is also called Young''s modulus for xylem.', 'MPa', 'num', 'Xylem modulus of elasticity', NULL, '10.0', '100000.0', FALSE),
(NULL, 'modulus_of_rupture', 'A measure of wood bending strength, which is the force per unit surface area applied to a length of bent stem (surface stress) that causes it to break. This is also the force required to rupture xylem vessels.', 'MPa', 'num', 'Modulus of rupture', NULL, '1.0', '10000.0', FALSE),
(NULL, 'photosynthetic_pathway', 'Type of photosynthetic pathway displayed by a plant.', NULL, 'cat.', 'Plant photosynthetic pathway', NULL, NULL, NULL, FALSE),
(NULL, 'bark_photosynthetic_status', 'Binary variable indicating whether bark is photosynthetic.', NULL, 'cat.', 'Bark photosynthesis', NULL, NULL, NULL, FALSE),
(NULL, 'leaf_photosynthetic_rate_per_area_ambient', 'The photosynthetic rate of a leaf exposed to ambient light (photosynthetically active radiation) levels and ambient carbon dioxide concentrations, air temperature and vapour pressure deficit, per unit leaf area.', 'umol{CO2}/m2/s', 'num', 'Leaf photosynthesis rate per unit leaf area under ambient light and CO2 (A)', NULL, '0.01', '40.0', FALSE),
(NULL, 'leaf_photosynthetic_rate_per_area_maximum', 'The photosynthetic rate of a leaf exposed to saturating light (photosynthetically active radiation) levels and saturating carbon dioxide concentrations, at optimal leaf temperature and VPD conditions, per unit leaf area; maximum photosynthetic rate.', 'umol{CO2}/m2/s', 'num', 'Leaf photosynthesis rate per unit leaf area under saturating light and CO2 (Amax)', NULL, '2.0', '65.0', FALSE),
(NULL, 'leaf_photosynthetic_rate_per_area_saturated', 'The photosynthetic rate of a leaf exposed to saturating light (photosynthetically active radiation) levels and ambient carbon dioxide concentrations, air temperature and vapour pressure deficit, per unit leaf area; light-saturated photosynthetic rate.', 'umol{CO2}/m2/s', 'num', 'Leaf photosynthesis rate per unit leaf area under saturating light and ambient CO2 (Asat)', NULL, '0.01', '50.0', FALSE),
(NULL, 'leaf_photosynthetic_rate_per_dry_mass_ambient', 'The photosynthetic rate of a leaf exposed to ambient light (photosynthetically active radiation) levels and ambient carbon dioxide concentrations, at ambient carbon dioxide concentrations, air temperature and vapour pressure deficit, per unit leaf dry mass.', 'umol{CO2}/g/s', 'num', 'Leaf photosynthesis rate per unit leaf dry mass under ambient light and CO2 (A)', NULL, '0.01', '0.8', FALSE),
(NULL, 'leaf_photosynthetic_rate_per_dry_mass_maximum', 'The photosynthetic rate of a leaf exposed to saturating light (photosynthetically active radiation) levels and saturating carbon dioxide concentrations, at optimal leaf temperature and VPD conditions, per unit leaf dry mass; maximum photosynthetic rate.', 'umol{CO2}/g/s', 'num', 'Leaf photosynthesis rate per unit leaf dry mass under saturating light and CO2 (Amax)', NULL, '0.01', '1.0', FALSE),
(NULL, 'leaf_photosynthetic_rate_per_dry_mass_saturated', 'The photosynthetic rate of a leaf exposed to saturating light (photosynthetically active radiation) levels and ambient carbon dioxide concentrations, air temperature and vapour pressure deficit,  per unit leaf dry mass; saturated photosynthetic rate.', 'umol{CO2}/g/s', 'num', 'Leaf photosynthesis rate per unit leaf dry mass under saturating light and ambient CO2 (Asat)', NULL, '0.001', '0.8', FALSE),
(NULL, 'leaf_intercellular_CO2_concentration_at_Amax', 'The CO2 concentration in intercellular (interstitial) spaces in a leaf exposed to saturating light (photosynthetically active radiation) levels and saturating carbon dioxide concentrations; ci.', 'umol{CO2}/mol', 'num', 'Leaf internal CO2 concentration during Amax measurement (ci)', NULL, '10.0', '1800.0', FALSE),
(NULL, 'leaf_intercellular_CO2_concentration_at_Asat', 'The CO2 concentration in intercellular (interstitial) spaces in a leaf exposed to saturating light (photosynthetically active radiation) levels and ambient carbon dioxide concentrations; ci.', 'umol{CO2}/mol', 'num', 'Internal CO2 concentration during Asat measurement (ci)', NULL, '10.0', '1300.0', FALSE),
(NULL, 'leaf_intercellular_CO2_concentration_at_Aambient', 'The CO2 concentration in intercellular (interstitial) spaces in a leaf exposed to ambient light (photosynthetically active radiation) levels and ambient carbon dioxide concentrations; ci.', 'umol{CO2}/mol', 'num', 'Internal CO2 concentration under ambient conditions (ci)', NULL, '10.0', '1300.0', FALSE),
(NULL, 'leaf_intercellular_CO2_concentration_to_atmospheric_CO2_concentration_ratio', 'The ratio of the CO2 concentration in intercellular (interstitial) spaces in leaves to the atmospheric CO2 concentration, an indication of stomatal conductance; ci/ca.', 'umol{CO2_internal}/umol{CO2_ambient}', 'num', 'Ratio of internal to external CO2 concentrations (ci/ca)', NULL, '0.001', '1.3', FALSE),
(NULL, 'leaf_chloroplast_CO2_concentration', 'CO2 concentration inside chloroplasts in leaves; cc.', 'umol{CO2}/umol', 'num', 'CO2 concentration inside chloroplasts (cc)', NULL, '10.0', '1000.0', FALSE),
(NULL, 'atmospheric_CO2_concentration', 'Atmospheric CO2 concentration (external CO2 concentration); ca.', 'umol{CO2}/mol', 'num', 'Ambient CO2 concentration (ca)', NULL, '50.0', '2000.0', FALSE),
(NULL, 'leaf_photosynthesis_Jmax_per_area', 'The maximum potential photosynthetic electron transport rate, recorded per unit leaf area. This is a model-derived value, calculated from the portion of an A-ci response curve (curve showing the photosynthetic response to increasing carbon dioxide concentrations) at high carbon dioxide concentrations. This is the portion of the curve where the photosynthetic rate is limited by the rate of  ATP and NADPH production by the light reactions.', 'umol/m2/s', 'num', 'Leaf Jmax per unit leaf area (Jmax)', NULL, '10.0', '800.0', FALSE),
(NULL, 'leaf_photosynthesis_Jmax_per_area_25C', 'The maximum potential photosynthetic electron transport rate, measured at 25 Celsius and recorded per unit leaf area. This is a model-derived value, calculated from the portion of an A-ci response curve (curve showing the photosynthetic response to increasing carbon dioxide concentrations) at high carbon dioxide concentrations. This is the portion of the curve where the photosynthetic rate is limited by the rate of  ATP and NADPH production by the light reactions.', 'umol/m2/s', 'num', 'Leaf Jmax per unit leaf area at 25 deg C (Jmax25)', NULL, '35.0', '800.0', FALSE),
(NULL, 'leaf_photosynthesis_Jmax_per_mass', 'The maximum potential photosynthetic electron transport rate, recorded per unit leaf mass. This is a model-derived value, calculated from the portion of an A-ci response curve (curve showing the photosynthetic response to increasing carbon dioxide concentrations) at high carbon dioxide concentrations. This is the portion of the curve where the photosynthetic rate is limited by the rate of  ATP and NADPH production by the light reactions.', 'umol/g/s', 'num', 'Leaf Jmax per unit leaf mass (Jmax)', NULL, '0.0', '3.0', FALSE),
(NULL, 'leaf_photosynthesis_Vcmax_per_area', 'The apparent maximum rate of Rubisco (ribulose 1,5-bisphosphate carboxylase/oxygenase) activity carboxylase activity (carboxylation capacity), recorded per unit leaf dry mass. This is a model-derived value, calculated from the portion of an A-ci response curve (curve showing the photosynthetic response to increasing carbon dioxide concentrations) at low carbon dioxide concentrations. This is the portion of the curve where the photosynthetic rate is limited by the Rubisco activity.', 'umol/m2/s', 'num', 'Leaf Vcmax per unit leaf area (Vcmax)', NULL, '10.0', '300.0', FALSE),
(NULL, 'leaf_photosynthesis_Vcmax_per_area_25C', 'The apparent maximum rate of Rubisco (ribulose 1,5-bisphosphate carboxylase/oxygenase) activity carboxylase activity (carboxylation capacity), measured at 25 Celsius and recorded per unit leaf area. This is a model-derived value, calculated from the portion of an A-ci response curve (curve showing the photosynthetic response to increasing carbon dioxide concentrations) at low carbon dioxide concentrations. This is the portion of the curve where the photosynthetic rate is limited by the Rubisco activity.', 'umol/m2/s', 'num', 'Leaf Vcmax per unit leaf area at 25 deg C (Vcmax25)', NULL, '10.0', '300.0', FALSE),
(NULL, 'leaf_photosynthesis_Vcmax_per_mass', 'The apparent maximum rate of Rubisco (ribulose 1,5-bisphosphate carboxylase/oxygenase) activity carboxylase activity (carboxylation capacity), recorded per unit leaf mass. This is a model-derived value, calculated from the portion of an A-ci response curve (curve showing the photosynthetic response to increasing carbon dioxide concentrations) at low carbon dioxide concentrations. This is the portion of the curve where the photosynthetic rate is limited by the Rubisco activity.', 'umol/g/s', 'num', 'Leaf Vcmax per unit leaf mass (Vcmax)', NULL, '0.0', '2.0', FALSE),
(NULL, 'leaf_photosynthesis_Jmax_over_Vcmax_25C', 'Ratio of photosynthetic electron transport capacity (Jmax) to maximum Rubisco activity (carboxylation capacity) (Vcmax). These are model-derived parameters, calculated from an A-ci response curve, reflecting, respectively the component of the curve where photosynthetic rates are limited by the light reactions versus low carbon dioxide concentrations.', '{dimensionless}', 'num', 'Leaf Jmax to leaf Vcmax ratio at 25 deg C', NULL, '1.0', '5.0', FALSE),
(NULL, 'leaf_fluorescence_fv_over_fm', 'A trait that indicates the health of photosystem II in a dark adapted leaf. Quantum yield is calculated as the ratio of variable fluorescence (Fv) to maximum fluorescence (Fm), with a higher value indicating a healthier leaf. Variable fluorescence (Fv) is calculated as the difference in fluorescence between a leaf where all photsystems have been saturated by light (Fm) and a leaf in a dark-adapted state (minimum fluorescence; Fo).', '{dimensionless}', 'num', 'Leaf maximum quantum yield (Fv/Fm)', NULL, '0.2', '1.0', FALSE),
(NULL, 'leaf_fluorescence_quantum_yield', 'A trait that indicates the health of photosystem II in a light adapted leaf. Quantum yield is calculated as the ratio of (maximum fluorescence under ambient conditions)-(fluorescence under ambient conditions)/(maximum fluorescence under ambient conditions).', '{dimensionless}', 'num', 'Leaf ambient quantum yield', NULL, '0.01', '1.0', FALSE),
(NULL, 'leaf_gas_exchange_quantum_yield', 'Ambient quantum yield of photosystem II, as determined through gas exchange measurements. Quantum yield is the ratio of photons absorbed to photons emitted through fluorescence.', '{dimensionless}', 'num', 'Leaf quantum yield, gas exchange measurement', NULL, '0.01', '1.0', FALSE),
(NULL, 'leaf_dark_respiration_per_area', 'The respiration rate of a leaf in the dark (absence of photosynthetically active radiation), calculated as the production of CO2 per unit leaf area.', 'nmol{CO2}/m2/s', 'num', 'Leaf respiration rate per unit leaf area, in the dark (Rdark)', NULL, '1.0', '15000.0', FALSE),
(NULL, 'leaf_dark_respiration_per_dry_mass', 'The respiration rate of a leaf in the dark (absence of photosynthetically active radiation), calculated as the production of CO2 per unit leaf dry mass.', 'nmol{CO2}/g/s', 'num', 'Leaf respiration rate per unit leaf dry mass, in the dark (Rdark)', NULL, '0.1', '1000.0', FALSE),
(NULL, 'leaf_light_respiration_per_area', 'The respiration rate of a leaf in ambient light (ambient photosynthetically active radiation), calculated as the production of CO2 per unit leaf area.', 'nmol{CO2}/m2/s', 'num', 'Leaf respiration rate per unit leaf area, in the light (Rday)', NULL, '10.0', '10000.0', FALSE),
(NULL, 'stem_dark_respiration_per_area', 'The respiration rate of a stem in the dark (absence of photosynthetically active radiation), calculated as the production of CO2 per unit stem area.', 'umol{CO2}/m2/s', 'num', 'Stem respiration rate per unit stem area, in the dark', NULL, '0.01', '10.0', FALSE),
(NULL, 'leaf_stomatal_conductance_per_area_ambient', 'The rate of gaseous water diffusion through stomata in a leaf exposed to ambient light (photosynthetically active radiation) levels and ambient carbon dioxide concentrations, recorded per unit leaf area.', 'mmol{H2O}/m2/s', 'num', 'Leaf stomatal conductance to water vapour per unit leaf area under ambient conditions (gsw)', NULL, '0.1', '2000.0', FALSE),
(NULL, 'leaf_stomatal_conductance_per_area_at_Amax', 'The rate of gaseous water diffusion through stomata in a leaf exposed to saturating light (photosynthetically active radiation) levels and saturating carbon dioxide concentrations, recorded per unit leaf area.', 'mmol{H2O}/m2/s', 'num', 'Leaf stomatal conductance to water vapour per unit leaf area during Amax measurement (gsw)', NULL, '0.1', '2000.0', FALSE),
(NULL, 'leaf_stomatal_conductance_per_area_at_Asat', 'The rate of gaseous water diffusion through stomata in a leaf exposed to saturating light (photosynthetically active radiation) levels and ambient carbon dioxide concentrations, recorded per unit leaf area.', 'mmol{H2O}/m2/s', 'num', 'Leaf stomatal conductance to water vapour per unit leaf area during Asat measurement (gsw)', NULL, '0.1', '2000.0', FALSE),
(NULL, 'leaf_stomatal_resistance_ambient', 'Leaf stomatal water vapour resistance under ambient light (photosynthetically active radiation) levels and ambient carbon dioxide concentrations.', 's/m', 'num', 'Leaf stomatal water vapour resistance under ambient conditions', NULL, '10.0', '1000000.0', FALSE),
(NULL, 'leaf_mesophyll_conductance_per_area', 'The rate of carbon dioxide movement between sub-stomatal cavities (intracellular space) and chloroplasts, per unit leaf area', 'mol{CO2}/m2/s', 'num', 'Leaf mesophyll conductance to carbon dioxide per unit leaf area (gm)', NULL, '0.01', '2000.0', FALSE),
(NULL, 'leaf_mesophyll_conductance_per_mass', 'The rate of carbon dioxide movement between sub-stomatal cavities (intracellular space) and chloroplasts, per unit leaf mass', 'mmol{CO2}/g/s', 'num', 'Leaf mesophyll conductance to carbon dioxide per unit leaf mass (gm)', NULL, '0.01', '10.0', FALSE),
(NULL, 'leaf_transpiration_per_area_ambient', 'The rate of water loss from a leaf exposed to ambient light (photosynthetically active radiation) levels and ambient carbon dioxide concentrations, recorded per unit leaf area.', 'mmol{H2O}/m2/s', 'num', 'Leaf transpiration per unit leaf area under ambient conditions (E)', NULL, '0.1', '50.0', FALSE),
(NULL, 'leaf_transpiration_per_area_at_Amax', 'The rate of water loss from a leaf exposed to saturating light (photosynthetically active radiation) levels and saturating carbon dioxide concentrations, recorded per unit leaf area.', 'mmol{H2O}/m2/s', 'num', 'Leaf transpiration per unit leaf area during Amax measurement (E)', NULL, '0.1', '50.0', FALSE),
(NULL, 'leaf_transpiration_per_area_at_Asat', 'The rate of water loss from a leaf exposed to saturating light (photosynthetically active radiation) levels and ambient carbon dioxide concentrations, recorded per unit leaf area.', 'mmol{H2O}/m2/s', 'num', 'Leaf transpiration per unit leaf area during Asat measurement (E)', NULL, '0.1', '50.0', FALSE),
(NULL, 'leaf_dark_transpiration_per_area', 'The rate of water loss from a leaf in the dark (no photosynthetically active radiation) and ambient carbon dioxide concentrations, recorded per unit leaf area.', 'mmol{H2O}/m2/s', 'num', 'Leaf transpiration rate per unit leaf area, in the dark', NULL, '0.0001', '10.0', FALSE),
(NULL, 'integrated_plant_transpiration', 'The rate of water loss integrated across an entire plant, as calculated across longer periods of time under experimental conditions, recorded per unit leaf area.', 'g/cm2{leaf}/d', 'num', 'Integrated plant transpiration', NULL, '0.01', '1.0', FALSE);
INSERT INTO traits (trait_type_name, trait_name, trait_info, trait_unit, trait_type, trait_label, column_number, allowed_values_min, allowed_values_max, of_interest) VALUES
(NULL, 'whole_plant_sapflow', 'The rate of water flow (velocity) through a plant stem, recorded per unit leaf area.', 'm3{H20}/m2{sapwood}/h', 'num', 'Whole plant sapflow', NULL, NULL, NULL, FALSE),
(NULL, 'leaf_photosynthetic_nitrogen_use_efficiency_maximum', 'The ratio of photosynthesis (CO2 assimilation rate) to leaf nitrogen content, where photosynthesis has been measured in a leaf exposed to saturating light (photosynthetically active radiation) levels and saturating carbon dioxide concentrations; PNUE.', 'umol{CO2}/g{N}/s', 'num', 'Leaf photosynthetic nitrogen use efficiency during Amax measurement (PNUE)', NULL, '0.1', '1000.0', FALSE),
(NULL, 'leaf_photosynthetic_nitrogen_use_efficiency_saturated', 'The ratio of photosynthesis (CO2 assimilation rate) to leaf nitrogen content, where photosynthesis has been measured in a leaf exposed to saturating light (photosynthetically active radiation) levels and ambient carbon dioxide concentrations; PNUE.', 'umol{CO2}/g{N}/s', 'num', 'Leaf photosynthetic nitrogen use efficiency during Asat measurement (PNUE)', NULL, '0.1', '1000.0', FALSE),
(NULL, 'leaf_photosynthetic_phosphorus_use_efficiency_maximum', 'The ratio of photosynthesis (CO2 assimilation rate) to leaf phosphorus content, where photosynthesis has been measured in a leaf exposed to saturating light (photosynthetically active radiation) levels and saturating carbon dioxide concentrations; PPUE.', 'umol{CO2}/g{P}/s', 'num', 'Leaf photosynthetic phosphorus use efficiency during Amax measurement PPUE)', NULL, '1.0', '10000.0', FALSE),
(NULL, 'leaf_photosynthetic_phosphorus_use_efficiency_saturated', 'The ratio of photosynthesis (CO2 assimilation rate) to leaf phosphorus content, where photosynthesis has been measured in a leaf exposed to saturating light (photosynthetically active radiation) levels and ambient carbon dioxide concentrations; PPUE.', 'umol{CO2}/g{P}/s', 'num', 'Leaf photosynthetic phosphorus use efficiency during Asat measurement (PPUE)', NULL, '1.0', '10000.0', FALSE),
(NULL, 'leaf_water_use_efficiency_integrated', 'The rate of carbon dioxide fixation relative to water loss, calculated as biomass production / transpiration. This measures how much biomass is produced relative to transpiration across a given time interval, and is therefore an integrated measure of water use efficiency; WUE, transpiration ratio', 'g{biomass}/g{H2O}', 'num', 'Integrated water use efficiency', NULL, '0.1', '50.0', FALSE),
(NULL, 'leaf_water_use_efficiency_intrinsic', 'The ratio of photosynthetic rate (A; CO2 assimilation rate) to stomatal conductance (gs; gaseous diffusion), with photosynthetic rate and stomatal conductance determined from gas exchange measurements.', 'umol{CO2}/mmol{H2O}', 'num', 'Intrinsic water use efficiency (WUEi)', NULL, '0.001', '2.0', FALSE),
(NULL, 'leaf_water_use_efficiency_instantaneous', 'The ratio of photosynthetic rate (A; CO2 assimilation rate) to transpiration rate (E; water loss), with photosynthetic rate and transpiration rate determined from gas exchange measurements, inside a leaf chamber. This is usually called instantaneous water use efficiency, but can also be referred to as photosynthetic water use efficiency (PWUE) or transpiration efficiency.', 'umol{CO2}/mmol{H2O}', 'num', 'Instantaneous water use efficiency (WUE)', NULL, '0.1', '200.0', FALSE),
(NULL, 'stem_hydraulic_conductivity', 'Kh; Measure of the efficiency of water flow through a stem segment. It is calculated as the ratio of the water flow rate (kg/s) to the water potential gradient (MPa) across the stem segment, multiplied by the stem length (m).', '10^6.kg.m/MPa/s', 'num', 'Stem hydraulic conductivity (Kh)', NULL, '0.01', '2000.0', FALSE),
(NULL, 'sapwood_specific_hydraulic_conductivity', 'Ks; Measure of the efficiency of water flow through a stem segment normalised to the sapwood cross-sectional area across which the flow is measured. It is calculated as the ratio of the water flow rate (kg/s) to the water potential gradient across the stem segment (MPa), divided by the sapwood cross sectional area (1/m2), then multiplied by the stem length (m).', 'kg/m/MPa/s', 'num', 'Sapwood specific hydraulic conductivity (Ks)', NULL, '0.01', '500.0', FALSE),
(NULL, 'sapwood_specific_hydraulic_conductivity_theoretical', 'Theoretical Ks; A calculation of the theoretical flow rate of water (kg/s) along a stem for a given drop in pressure (MPa), normalised to the microscopically determined cross-sectional area without bark and pith (the diameter of water transport tissues). The calculation is based on Hagen-Poiseuille''s law.', 'kg/m/MPa/s', 'num', 'Theoretical sapwood specific hydraulic conductivity (Ks)', NULL, '0.05', '5000.0', FALSE),
(NULL, 'stem_specific_hydraulic_conductivity', 'Ks; Measure of the efficiency of water flow through a stem segment normalised to the stem (sapwood + bark) cross-sectional area across which the flow is measured. It is calculated as the ratio of the water flow rate (kg/s) to the water potential gradient across the stem segment (MPa), divided by the stem cross sectional area (1/m2), then multiplied by the stem length (m).', 'kg/m/MPa/s', 'num', 'Stem specific hydraulic conductivity (Ks)', NULL, '0.01', '500.0', FALSE),
(NULL, 'leaf_specific_hydraulic_conductance', 'kleaf; Measure of how efficiently water is transported through a leaf. It is calculated as the ratio of water flow rate through the leaf (mmol/s) to the water potential gradient from the petiole to mesophyll substomatal cavities (MPa), divided by the leaf area (1/m2). As this is a measure of "conductance" not "conductivity" the measurement is not normalised to the path length (the leaf length).', 'mmol/m2/MPa/s', 'num', 'Leaf specific hydraulic conductance (kleaf)', NULL, '0.1', '100.0', FALSE),
(NULL, 'leaf_specific_hydraulic_conductivity', 'Kl; Measure of the efficiency of water flow through a stem segment, normalised to the total leaf area distil to the stem segment.  It is calculated as the ratio of the water flow rate (kg/s) to the water potential gradient across the stem segment (MPa), divided by the total leaf area (1/m2), then multiplied by the stem length (m).', '10^4.kg/m/MPa/s', 'num', 'Leaf specific hydraulic conductivity (Kl)', NULL, '0.1', '500.0', FALSE),
(NULL, 'root_hydraulic_conductivity', 'Kh; Measure of the efficiency of water flow through a root segment. It is calculated as the ratio of the water flow rate (kg/s) to the water potential gradient (MPa) across the root segment, multiplied by the root length (m).', '10^6.kg.m/MPa/s', 'num', 'Root hydraulic conductivity (Kh)', NULL, '0.01', '2000.0', FALSE),
(NULL, 'root_specific_hydraulic_conductivity', 'Measure of the efficiency of water flow through a root segment normalised to the root cross-sectional area across which the flow is measured. It is calculated as the ratio of the water flow rate (kg/s) to the water potential gradient across the root segment (MPa), divided by the root cross sectional area (1/m2), then multiplied by the root length (m).', 'kg/m/MPa/s', 'num', 'Root specific hydraulic conductivity', NULL, '0.01', '500.0', FALSE),
(NULL, 'water_potential_predawn', 'The water potential of a plant''s shoot system just before sunrise, a proxy for soil water potential and the plant''s highest (least negative) water potential for the day.', 'MPa', 'num', 'Pre-dawn water potential', NULL, '-20.0', '0.0', FALSE),
(NULL, 'water_potential_midday', 'The water potential of a plant''s leaf or shoot photosynthetic tissue during maximum midday transpiration, the time of day when the plant is most water stressed and has the lowest (most negative) water potential.', 'MPa', 'num', 'Midday water potential', NULL, '-20.0', '0.0', FALSE),
(NULL, 'stem_sapwood_capacitance', 'The ratio of the change in stem tissue water volume to the change in stem tissue water potential.', 'kg{H20}/m3/MPa', 'num', 'Stem sapwood capacitance (C)', NULL, '0.0', '700.0', FALSE),
(NULL, 'leaf_capacitance', 'The ratio of the change in leaf tissue water volume to the change in leaf tissue water potential.', '1/MPa', 'num', 'Leaf capacitance (Cleaf)', NULL, '0.0', '70.0', FALSE),
(NULL, 'root_sapwood_capacitance', 'The ratio of the change in root tissue water volume to the change in root tissue water potential.', 'kg{H20}/m3/MPa', 'num', 'Root sapwood capacitance (C)', NULL, '0.0', '700.0', FALSE),
(NULL, 'leaf_hydraulic_vulnerability', 'A measure of leaf hydraulic vulnerability, which is the leaf xylem water pressure at which leaf hydraulic conductance has declined by 50% from the mean maximum rate of hydraulic conductance.', 'MPa', 'num', 'Leaf xylem pressure, 50% lost conductance (P50)', NULL, '-40.0', '0.0', FALSE),
(NULL, 'water_potential_12percent_lost_conductivity', 'A measure of stem hydraulic vulnerability, which is the stem xylem water pressure value at which stem hydraulic conductivity has declined by 12% from the mean maximum rate of hydraulic conductivity.', 'MPa', 'num', 'Stem xylem pressure, 12% lost conductivity (P12)', NULL, '-20.0', '0.0', FALSE),
(NULL, 'water_potential_50percent_lost_conductivity', 'A measure of stem hydraulic vulnerability, which is the stem xylem water pressure value at which stem hydraulic conductivity has declined by 50% from the mean maximum rate of hydraulic conductivity.', 'MPa', 'num', 'Stem xylem pressure, 50% lost conductivity (P50)', NULL, '-20.0', '0.0', FALSE),
