(NULL, 'hydraulic_safety_margin_50', 'The difference between the stem water potential at turgor loss and the water potential at which 50% of conductivity is lost.', 'MPa', 'num', 'Hydraulic safety margin, 50%', NULL, '-5.0', '10.0', FALSE),
(NULL, 'hydraulic_safety_margin_88', 'The difference between the stem water potential at turgor loss and the water potential at which 88% of conductivity is lost.', 'MPa', 'num', 'Hydraulic safety margin, 88%', NULL, '-5.0', '10.0', FALSE),
(NULL, 'leaf_turgor_loss_point', 'A parameter calculated from a pressure-volume curve which is the water potential at which the mean cell turgor pressure in the leaf/shoot declines to zero.', 'MPa', 'num', 'Leaf turgor loss point', NULL, '-5.0', '0.0', FALSE),
(NULL, 'osmotic_potential', 'The potential energy of water molecules to move across a semi-permeable membrane due to differences in solute concentration across the membrane; solute potential', 'MPa', 'num', 'Osmotic potential', NULL, '-10.0', '0.0', FALSE),
(NULL, 'osmotic_potential_at_full_turgor', 'A parameter calculated from a pressure-volume curve which is the osmotic potential (solute potential) in leaf cells at full turgor (when relative water content = 100%). Osmotic potential is the energy of water molecules to move across a semi-permeable membrane due to differences in solute concentration across a membrane and is least negative (largest) when plants are at full turgor.', 'MPa', 'num', 'Osmotic potential at full tugor', NULL, '-10.0', '-0.1', FALSE),
(NULL, 'bulk_modulus_of_elasticity', 'A parameter calculated from a pressure-volume curve which indicates the elasticity or rigidity of cells in leaves. It is the ratio of the change in cell turgor potential to the change in relative cell volume (change in volume/initial volume).', 'MPa', 'num', 'Bulk modulus of elasticity (e)', NULL, '0.1', '100.0', FALSE),
(NULL, 'leaf_relative_water_content_predawn', 'Ratio of the mass of water in a fresh leaf collected pre-dawn to the mass of water in a fully saturated leaf. A fully saturated leaf is one which has been rehydrated to hold the maximum amount of water and is considered to have a relative water content of 100%.', 'g/g', 'num', 'Leaf relative water content predawn', NULL, '0.1', '1.4', FALSE),
(NULL, 'leaf_relative_water_content_at_turgor_loss_point', 'Ratio of the mass of water in leaf at the point the leaf cells lose turgor to the mass of water in a fully saturated leaf. A fully saturated leaf is one which has been rehydrated to hold the maximum amount of water and is considered to have a relative water content of 100%. The plant''s turgor loss point is calculated from a pressure-volume curve.', 'g/g', 'num', 'Leaf relative water content at turgor loss point', NULL, '0.1', '1.0', FALSE),
(NULL, 'root_water_potential_50percent_lost_conductivity', 'A measure of root hydraulic vulnerability, which is the root xylem water pressure value at which root hydraulic conductivity has declined by 50% from the mean maximum rate of hydraulic conductivity.', 'MPa', 'num', 'Root xylem pressure, 50% lost conductivity (P50)', NULL, '-20.0', '0.0', FALSE),
(NULL, 'root_water_potential_12percent_lost_conductivity', 'A measure of root hydraulic vulnerability, which is the root xylem water pressure value at which root hydraulic conductivity has declined by 12% from the mean maximum rate of hydraulic conductivity.', 'MPa', 'num', 'Root xylem pressure, 12% lost conductivity (P12)', NULL, '-20.0', '0.0', FALSE),
(NULL, 'root_water_potential_88percent_lost_conductivity', 'A measure of root hydraulic vulnerability, which is the root xylem water pressure value at which root hydraulic conductivity has declined by 88% from the mean maximum rate of hydraulic conductivity.', 'MPa', 'num', 'Root xylem pressure, 88% lost conductivity (P88)', NULL, '-20.0', '0.0', FALSE),
(NULL, 'leaf_water_potential_12percent_lost_conductivity', 'A measure of leaf hydraulic vulnerability, which is the leaf xylem water pressure at which leaf hydraulic conductance has declined by 12% from the mean maximum rate of hydraulic conductance.', 'MPa', 'num', 'Leaf xylem pressure, 12% lost conductance (P12)', NULL, '-40.0', '0.0', FALSE),
(NULL, 'leaf_water_potential_88percent_lost_conductivity', 'A measure of leaf hydraulic vulnerability, which is the leaf xylem water pressure at which leaf hydraulic conductance has declined by 88% from the mean maximum rate of hydraulic conductance.', 'MPa', 'num', 'Leaf xylem pressure, 88% lost conductance (P88)', NULL, '-40.0', '0.0', FALSE),
(NULL, 'leaf_photochemical_reflectance_index', 'Photochemical reflectance index measures plant responses to stress and the efficiency with which it uses photosynthetically active radiation, by indicating changes in carotenoid pigments in live foliage.  It is calculated from the reflectance of radiation off the plant canopy at 531 nm (a xanthophyll band) and 570 nm (a reference band): PRI = (R531 - R570) / (R531 + R570), with a higher value indicating higher radiation use efficiency.', '{dimensionless}', 'num', 'Photochemical reflectance index (PRI)', NULL, '-1.0', '1.0', FALSE),
(NULL, 'leaf_water_band_index', 'Water band index measures whole plant water status. It is the ratio of the reflectance of radiation off the plant canopy at 970 nm to the reflectance at 900 nm; a higher value indicates a higher canopy water content.', '{dimensionless}', 'num', 'Water band index', NULL, '1.0', '1.1', FALSE),
(NULL, 'modified_NDVI', 'A remote sensing index of whole plant vegetation status, which is a ratio that considers the relative reflectance of red light versus short-wave infrared radiation (SWIR) off the plant canopy, where a higher value indicates greater vegetation health. The formula is: (SWIR - Red) / (SWIR + Red).', '{dimensionless}', 'num', 'Modified normalized difference vegetation index (modified NDVI)', NULL, '0.1', '1.0', FALSE),
(NULL, 'leaf_chlorophyll_index_modified_ND705', 'A remote sensing index of chlorophyll absorption, which is a ratio that considers the relative reflectance of different wavelengths off the plant canopy, where a higher value indicates greater chlorophyll absorption. The formula is: (R750-R705)/(R750+R705+2(R445)).', '{dimensionless}', 'num', 'Modified chlorophyll absorption ratio index 705', NULL, '0.1', '1.0', FALSE),
('Descriptive', 'plant_growth_form', 'The form of a plant, capturing a general sense of plant height and shape, which parts of a plant are woody versus herbaceous, the number of stems arising at ground level, and the distribution of leaves relative to the main stem.', NULL, 'cat.', 'Plant growth form', '8', NULL, NULL, TRUE),
(NULL, 'life_form', 'Raunkiaer classification of life form, indicating the location of and protection provided to surviving meristematic tissue (buds) during the unfavourable (cold or dry) season.', NULL, 'cat.', 'Life form', NULL, NULL, NULL, FALSE),
('Life history', 'life_history', 'Categorical description of the duration of a plant''s lifespan, from germination to death.', NULL, 'cat.', 'Life history', '12', NULL, NULL, TRUE),
