('Natural Growth', 'stem_growth_habit', 'Trait characterising a stem''s structure and 3-dimensional extent, including the position of stems, degree of branchiness, density of branches, and branch angles relative to other branches and the ground surface.', NULL, 'cat.', 'Stem growth habit', '54', NULL, NULL, TRUE),
