('Natural Growth', 'nitrogen_fixing', 'Binary variable describing whether a plant has the capacity for nitrogen fixatation, indicating it engages in symbioses with microorganisms (most commonly bacteria or cyanobacteria) that are capable of nitrogen fixation. Nitrogen fixation capacity is usually identified by nodules on the plant roots.', NULL, 'cat.', 'Plant nitrogen fixation capacity', '51', NULL, NULL, TRUE),
('Germination', 'root_structure', 'Specific specialized types of root structures and root symbioses, especially symbioses with mycorrhizal fungi.', NULL, 'cat.', 'Plant root structures', '31', NULL, NULL, TRUE),
