('Botany', 'sex_type', 'Plant sex type, indicating, for a taxon the type of flowers (male, female, and hermaphroditic) present on individual plants versus separate plants within a population.', NULL, 'cat.', 'Plant sex type', '63', NULL, NULL, TRUE),
('Pollination', 'pollination_syndrome', 'For a given taxon, the biotic vectors (including explicit taxa) or abiotic mechanisms that are most likely to pollinate its flowers, based on the taxon''s flower morphology.', NULL, 'cat.', 'Pollination syndrome', '36', NULL, NULL, TRUE),
