('Seeds', 'reproductive_maturity', 'The age of a plant when they are able to set seed, indicating it is reproductively mature.', 'a', 'num', 'Age of reproductive maturity', '45', '0.1', '1000.0', TRUE),
('Natural Growth', 'dispersal_syndrome', 'Plant dispersal syndromes are generally assigned to species based on suites of diaspore characteristics associated with specific mechanisms of dispersal. Trait values are mostly given as the formal dispersal syndromes ending in ''chory'', a suffix meaning ''a specified method of plant dispersal''.', NULL, 'cat.', 'Diaspore dispersal syndrome', '49', NULL, NULL, TRUE),
('Natural Growth', 'dispersers', 'Dominant diaspore dispersal agents, including both biotic agents (specific taxa) or abiotic mechanisms responsible for dispersing seeds (or other dispersal units) away from the parent plant.', NULL, 'cat.', 'Diaspore dispersal agents', '50', NULL, NULL, TRUE),
