('Seedbank', 'seedbank_longevity_class', 'Categorical groupings indicating the length of time (duration) a mature seed remains in the seedbank, viable and able to germinate.', NULL, 'cat.', 'Seedbank longevity class', '42', NULL, NULL, TRUE),
('Seedbank', 'seedbank_longevity', 'The half-life of the seedbank, which is the length of time (duration) from when seeds in a seedbank mature until more than half the seeds in a seedbank are no longer able to germinate.', 'a', 'num', 'Seedbank longevity', '41', '0.01', '1000.0', TRUE),
('Propagation', 'seed_dormancy_class', 'Mechanisms that inhibit mature seeds from germinating and the environmental or experimental cues that allow a seed to break dormancy and germinate.', NULL, 'cat.', 'Dormancy type', '38', NULL, NULL, TRUE),
('Propagation', 'seed_germination_treatment', 'Treatment required for seed to display high germination rates. The data included in AusTraits are mostly from seed banks that have recorded the protocols they use to encourage seeds to germinate. The treatments may therefore be only loosely connected to the cues required for a species'' to break dormancy.', NULL, 'cat.', 'Seed germination treatment', '39', NULL, NULL, TRUE),
('Germination', 'seed_germination', 'Proportion of mature seeds in a sample that germinated under specified environmental or experimental conditions.', '{count}/{count}', 'num', 'Seed germination proportion', '32', '0.0', '1.0', TRUE),
