('Natural Growth', 'vegetative_reproduction_ability', 'A binary trait, indicating whether a plant taxon is able to reproduce and spread through the growth and division of vegetative material.', NULL, 'cat.', 'Vegetative reproduction ability', '56', NULL, NULL, TRUE),
('Botany', 'clonal_spread_mechanism', 'Mechanisms and structures (tissues, organs, or other structures) a plant uses to spread vegetatively, including the production of clones.', NULL, 'cat.', 'Clonal spread mechanism', '58', NULL, NULL, TRUE),
('Natural Growth', 'storage_organ', 'Plant structures  (tissues, organs, or other structures) where a plant stores excess carbohydrates (energy). The stored energy may be used for future growth, including clonal spread and regrowth following an annual unfavourable season, or for regrowth following a disturbance event (including post-fire regeneration or another disturbance event that causes leaf loss). Trait values include both generic terms and quite specific ones to accommodate the variation in detail provided across datasets.', NULL, 'cat.', 'Storage organ', '55', NULL, NULL, TRUE),
('Botany', 'bud_bank_location', 'The location of buds (meristematic tissue) on a plant that allows it to resprout following a fire, annual unfavourable season, or other disturbance event, such as a drought or cyclone. Trait values include both generic terms and quite specific ones to accommodate the variation in detail provided across datasets.', NULL, 'cat.', 'Bud bank location', '57', NULL, NULL, TRUE),
('Natural Growth', 'sprout_depth', 'Depth below the soil surface (positive number) or height above ground (negative number) from which buds (meristematic tissue) resprout following a disturbance, such as a fire.', 'mm', 'num', 'Sprout depth', '53', '-100.0', '100.0', TRUE),
('Fire response', 'resprouting_capacity', 'Trait indicating whether mature individuals of a taxon are killed, resprout, or have a mixed survival response when exposed to fire that causes 100% leaf scorch.  Species where at least 70% of plants resprout are designated `resprouters`, while those where fewer than 30% of plants resprout are designated as `fire killed`. Species with an intermediate response have a mixed fire response, and are coded as `fire_killed resprouts`.', NULL, 'cat.', 'Post-fire resprouting capacity', '24', NULL, NULL, TRUE),
('Fire response', 'resprouting_capacity_proportion_individuals', 'Proportion of mature individuals in a population that survive a fire and resprout following a fire.', '{count}/{count}', 'num', 'Post-fire proportion resprouting individuals', '26', '0.0', '1.0', TRUE),
('Fire response', 'resprouting_capacity_juvenile', 'Trait indicating whether juvenile phase individuals of a taxon are killed, resprout, or have a mixed survival response when exposed to a fire with 100% leaf scorch.', NULL, 'cat.', 'Post-fire resprouting capacity of juvenile plants', '25', NULL, NULL, TRUE),
('Fire response', 'resprouting_capacity_time_from_germination', 'A fire response trait which is the time from seed germination until individuals are able to survive and resprout following a fire where 100% of the leaves in the canopy are scorched.', 'a', 'num', 'Time from seedling germination until individuals survive a fire', '27', '0.1', '100.0', TRUE),
(NULL, 'resprouting_capacity_stem_ratio', 'Ratio of stem count post-fire to basal stem count (e.g. grass tillers) pre-fire at an individual or population level. This trait is appropriate to score for plants that have many stems from the base (shrubs, herbs, graminoids) where the number of stems is censused both before and after the fire. It is a continuous measure of resprouting strength conditioned on initial size.', '{count}/{count}', 'num', 'Post-fire to pre-fire stem ratio', NULL, '0.0', '10.0', FALSE),
('Natural Growth', 'resprouting_capacity_non_fire_disturbance', 'A plant''s ability to regenerate vegetatively (resprout) from a disturbance other than fire that causes 100% defoliation.', NULL, 'cat.', 'Plant vegetative response to disturbances other than fire', '52', NULL, NULL, TRUE),
(NULL, 'fire_exposure_level', 'Trait indicating habitat (or microhabitat) variation that protects the shoot or root system of some taxa from being exposed to fire and scorched by the fire, even when a fire burns nearby.', NULL, 'cat.', 'Fire exposure level', NULL, NULL, NULL, FALSE),
('Fire response', 'post_fire_recruitment', 'A trait indicating the magnitude of seed germination and seedling establishment following a fire.', NULL, 'cat.', 'Post-fire recruitment', '23', NULL, NULL, TRUE),
('Fire response', 'post_fire_flowering', 'Indication of whether the magnitude of flowers produced by a taxon increases, decreases or remains unchanged following a fire.', NULL, 'cat.', 'Post-fire flowering', '22', NULL, NULL, TRUE),
('Fire recovery', 'fire_time_from_fire_to_flowering', 'The time interval from a fire until the first individual in a population begins flowering.', 'mo', 'num', 'Time from fire to first flowering', '16', '1.0', '1000.0', TRUE),
