('Fire recovery', 'fire_time_from_fire_to_fruiting', 'The time interval from a fire until the first individual in a population produces a mature fruit with viable propagules.', 'mo', 'num', 'Time from fire to fruiting', '18', '1.0', '500.0', TRUE),
('Fire recovery', 'fire_time_from_fire_to_50_percent_fruiting', 'The time interval from a fire until 50% of the individuals in a population produce mature fruit.', 'mo', 'num', 'Time from fire until 50% of individuals are fruiting', '15', '1.0', '500.0', TRUE),
(NULL, 'fire_fuel_bed_bulk_density', 'The density of the fuel bed, the plant litter accumulated on the ground. It is calculated as the ratio of the mass of the fuel bed to the fuel bed volume. This trait should be measured on plant litter from a single taxon.', 'g/cm3', 'num', 'Fuel bed bulk density', NULL, '0.001', '1.0', FALSE),
(NULL, 'fire_fuel_consumption', 'Proportion of available plant biomass (live and dead) that is consumed by fire. This trait should be measured on biomass from a single taxon.', 'g/g', 'num', 'Fuel consumption by fire', NULL, '0.1', '100.0', FALSE),
